import { mkdir, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import { format, resolveConfig } from "prettier";

import { factoryReadOpenApi } from "../src/lib/factory-read-api/openapi";

const sourceDirectory = new URL("../packages/factory-client/src/", import.meta.url);
const header =
  "// Generated by pnpm factory:client:generate from the published Factory API contract.";
const filenames = ["schema.ts", "operations.ts"] as const;
type GeneratedFile = (typeof filenames)[number];

type RouteOperation = {
  operationId: string;
  parameters: readonly { in: string; name: string; required: boolean }[];
};

function operationSource(paths: Record<string, Partial<Record<"get" | "post", RouteOperation>>>) {
  const operations = new Map<
    string,
    { method: "GET" | "POST"; path: string; requiresIdempotencyKey: boolean }
  >();
  for (const [path, route] of Object.entries(paths)) {
    for (const method of ["get", "post"] as const) {
      const operation = route[method];
      if (!operation) continue;
      if (operations.has(operation.operationId)) {
        throw new Error(`Duplicate Factory API operation ID ${operation.operationId}.`);
      }
      const requiresIdempotencyKey = operation.parameters.some(
        (param) =>
          param.in === "header" && param.name.toLowerCase() === "idempotency-key" && param.required,
      );
      operations.set(operation.operationId, {
        method: method === "get" ? "GET" : "POST",
        path,
        requiresIdempotencyKey,
      });
    }
  }

  const entries = [...operations].sort(([left], [right]) => left.localeCompare(right, "en"));
  const values = JSON.stringify(Object.fromEntries(entries), null, 2);
  return `import type { operations, paths } from "./schema.js";

type FactoryOperation = {
  method: "GET" | "POST";
  path: keyof paths;
  requiresIdempotencyKey: boolean;
};

export const factoryOperations = ${values} as const satisfies Record<keyof operations, FactoryOperation>;

export type FactoryOperationId = keyof typeof factoryOperations;
`;
}

export async function generateFactoryClientSources(): Promise<Record<GeneratedFile, string>> {
  const ast = await openapiTS(JSON.stringify(factoryReadOpenApi), { alphabetize: true });
  const config = await resolveConfig(fileURLToPath(new URL("schema.ts", sourceDirectory)));
  const options = { ...config, parser: "typescript" };
  const [schema, operations] = await Promise.all([
    format(`${header}\n${astToString(ast)}`, options),
    format(`${header}\n${operationSource(factoryReadOpenApi.paths)}`, options),
  ]);
  return { "schema.ts": schema, "operations.ts": operations };
}

async function writeFactoryClientSources() {
  const files = await generateFactoryClientSources();
  await mkdir(sourceDirectory, { recursive: true });
  await Promise.all(
    filenames.map((file) => writeFile(new URL(file, sourceDirectory), files[file])),
  );
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFactoryClientSources().catch((error: unknown) => {
    console.error(error);
    process.exitCode = 1;
  });
}
